import type { GuideSection } from "./types";

export const GUIDE_CONTENT_A: Record<string, GuideSection[]> = {
  "first-time-buyer-checklist": [
    { heading: "Phase 1 — Financial Prep (3–6 Months Before)", paragraphs: ["Check your credit score (aim for 680+). Calculate how much you can afford including the mortgage stress test. Open a First Home Savings Account (FHSA) — contributions are tax-deductible and withdrawals for a first home are completely tax-free. Get a mortgage pre-approval before you start shopping — most sellers won't take an offer seriously without one. Pre-approval verifies your income, locks a rate for 90–120 days, and sets your real budget."], checklist: [] },
    { heading: "Phase 2 — Find Your Home", paragraphs: ["Hire a buyer's agent — their commission is paid by the seller, not you. Before your first showing, write out your must-haves vs nice-to-haves. Research neighbourhoods: walk scores, transit, schools, and any future development plans. Attend open houses and track recent sold prices — not list prices — for comparable homes. Sold data is your anchor; list prices are marketing."], checklist: [] },
    { heading: "Phase 3 — Make an Offer", paragraphs: ["Review comparable solds from the last 90 days with your agent. Decide on conditions: a financing condition protects you if your mortgage falls through; an inspection condition lets you negotiate repairs or exit the deal. Include a realistic deposit (typically 5% of the purchase price). Confirm your closing date aligns with your mortgage commitment period."], checklist: [] },
    { heading: "Phase 4 — Between Offer and Closing", paragraphs: ["Complete your home inspection — attend in person and ask every question you have. Review the title search your lawyer provides. Confirm your mortgage is fully committed. Arrange home insurance before closing day — your lender requires proof. Do a final walkthrough 24–48 hours before closing to confirm the property is in the agreed condition."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Check credit score and fix errors", "Open FHSA account", "Get mortgage pre-approval", "Hire a buyer's agent", "List must-haves vs nice-to-haves", "Research target neighbourhoods", "Review recent sold prices", "Make an offer with conditions", "Complete home inspection", "Hire a real estate lawyer", "Arrange home insurance", "Final walkthrough", "Receive keys on closing day"] },
  ],
  "mortgage-preapproval-explained": [
    { heading: "Pre-Qualification vs Pre-Approval", paragraphs: ["Pre-qualification is a 10-minute online estimate based on self-reported numbers — it carries no weight with sellers. Pre-approval involves verifying your income, employment, credit score, and assets. A pre-approved buyer has a rate locked for 90–120 days and a confirmed borrowing limit. In competitive markets, sellers often won't accept an offer from a buyer without a current pre-approval letter."], checklist: [] },
    { heading: "What Lenders Examine", paragraphs: ["Employment and income: T4s, Notices of Assessment (NOAs), and recent pay stubs for the past 2 years. Credit score: minimum 600 for insured mortgages; 680+ preferred for conventional. Debt ratios: GDS (gross debt service — housing costs divided by gross income) must be 32% or less; TDS (total debt service — all debts divided by income) must be 44% or less. Stress test: you must qualify at your offered rate plus 2%, or 5.25%, whichever is higher."], checklist: [] },
    { heading: "What Pre-Approval Does NOT Guarantee", paragraphs: ["It is not a commitment to lend. The property itself must also be approved by the lender — they assess the home's value and condition. Your financial situation must remain unchanged: avoid new debt, job changes, or large purchases between pre-approval and closing. Rate holds expire — typically 90–120 days. If your purchase takes longer, reapply early."], checklist: [] },
    { heading: "Tips to Strengthen Your Application", paragraphs: ["Pay down existing revolving debt before applying — credit utilization above 50% hurts your score significantly. Avoid applying for new credit cards or loans in the 6 months before. Two or more years of consistent employment in the same field or industry is ideal. If self-employed, expect to provide 2 years of NOAs, T1 generals, and business financial statements. Work with a mortgage broker who can compare 20+ lenders simultaneously."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Pull your own credit report first (free at Borrowell)", "Gather T4s and NOAs for 2 years", "List all monthly debt payments", "Contact a mortgage broker and 1–2 direct lenders", "Submit full application with all documents", "Receive pre-approval letter", "Note exact rate hold expiry date", "Avoid all new debt until after closing"] },
  ],
  "cmhc-insurance-guide": [
    { heading: "What CMHC Insurance Actually Is", paragraphs: ["CMHC (Canada Mortgage and Housing Corporation) insurance protects the lender — not you — if you default on your mortgage. Despite protecting the lender, you pay the entire premium. It is required by law on all mortgages with less than 20% down on homes valued under $1.5 million. Three providers offer this insurance: CMHC, Sagen, and Canada Guaranty — your lender chooses which one."], checklist: [] },
    { heading: "Premium Rates and Real Numbers", paragraphs: ["Down payment 5%–9.99%: premium is 4.00% of the mortgage amount. Down payment 10%–14.99%: 3.10%. Down payment 15%–19.99%: 2.80%. The premium is added to your mortgage balance — you don't pay it in cash upfront, but you do pay interest on it over the life of the loan. Example: $600,000 home with 5% down ($30,000). Insured mortgage: $570,000. Premium: $22,800 (4%). Total mortgage: $592,800."], checklist: [] },
    { heading: "How to Avoid CMHC Insurance", paragraphs: ["Save a full 20% down payment. Use the First Home Savings Account — contribute up to $8,000/year (lifetime max $40,000) and withdraw tax-free for a first home purchase. Use the RRSP Home Buyers' Plan — withdraw up to $35,000 from your RRSP tax-free (must be repaid over 15 years). Receive a documented gift from an immediate family member — must be proven as a true gift, not a loan."], checklist: [] },
    { heading: "Provincial Sales Tax on the Premium", paragraphs: ["Ontario and Quebec charge provincial sales tax on the CMHC premium. This PST must be paid in cash at closing — it cannot be added to the mortgage. In Ontario, PST is 8% of the premium amount. On a $22,800 premium, that's $1,824 in Ontario PST due on closing day. Budget for this separately in your closing cost estimate — it surprises many buyers."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate your down payment percentage", "Look up premium rate for your tier", "Calculate total premium on your mortgage", "Check if your province charges PST on the premium", "Explore FHSA to build tax-free down payment", "Explore RRSP Home Buyers' Plan", "Confirm property is under $1.5M CMHC limit", "Ask lender to show amortized cost of CMHC premium"] },
  ],
  "closing-costs-guide": [
    { heading: "Land Transfer Tax", paragraphs: ["Ontario: 0.5% on the first $55,000 of purchase price; 1.0% up to $250,000; 1.5% up to $400,000; 2.0% above $400,000; plus 2.5% above $2M on non-residential portions. Toronto buyers pay a second identical municipal LTT on top of provincial. First-time buyers receive a provincial rebate of up to $4,000 and a Toronto rebate of up to $4,475. BC, Alberta, Manitoba, and other provinces each have different rates — calculate before you make an offer."], checklist: [] },
    { heading: "Legal Fees and Disbursements", paragraphs: ["Budget $1,200–$2,500 for a real estate lawyer or notary. Your lawyer reviews the Agreement of Purchase and Sale, performs a title search, handles the transfer of funds, registers the mortgage and new title, and provides a statement of adjustments showing every credit and debit on closing day. Never attempt to close a real estate purchase without a lawyer — they catch problems you don't know to look for."], checklist: [] },
    { heading: "Title Insurance", paragraphs: ["A one-time premium of $200–$400 for an owner's title insurance policy. This covers undisclosed title defects, zoning violations, survey issues, and title fraud. Your lender requires a lender's policy; purchase your own separate owner's policy for personal protection — the added cost is minimal. Title fraud (where someone sells your home without your knowledge) is rare but devastating; title insurance is protection against it."], checklist: [] },
    { heading: "Other Closing Costs", paragraphs: ["Home inspection: $400–$600. Property tax adjustment: you reimburse the seller for any property tax they've prepaid past your closing date. Utility hookup or transfer fees. Moving costs: $1,000–$5,000+ depending on volume and distance. For condos: status certificate review costs your lawyer extra time ($100–$200). For new builds: HST new housing rebate and Tarion enrollment fee. Ask your lawyer for a full estimated statement of adjustments before closing so nothing surprises you."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate LTT for your province and municipality", "Check first-time buyer LTT rebate eligibility", "Budget $1,200–$2,500 for legal fees", "Get title insurance (owner's policy)", "Confirm inspection cost ($400–$600)", "Ask lawyer for estimated statement of adjustments", "Set aside 2%–4% of purchase price total for closing", "Budget for PST on CMHC premium if applicable", "Confirm utility transfer dates", "Budget for moving costs"] },
  ],
  "condo-vs-freehold": [
    { heading: "What You Own With Each", paragraphs: ["Freehold: you own the land, the structure, and everything in it outright. Your decisions about the property are your own, subject only to municipal zoning. No monthly fees to a corporation. Condo: you own your unit plus a proportional share of the common elements. The condo corporation — governed by elected owners — manages everything outside your unit: hallways, elevators, roof, mechanical systems, amenities. Your monthly maintenance fee funds all of this."], checklist: [] },
    { heading: "Monthly Costs Compared", paragraphs: ["Freehold has no maintenance fee — but you pay 100% of all repairs, insurance, and upkeep personally. A new roof can cost $15,000–$30,000; an HVAC replacement $5,000–$15,000. Condos charge $400–$900/month in maintenance fees in most major Canadian cities, covering building insurance, common area upkeep, and often heat and water. The real risk: a special assessment when the reserve fund is inadequate — this can be tens of thousands of dollars with short notice."], checklist: [] },
    { heading: "What to Check Before Buying a Condo", paragraphs: ["The status certificate is essential — your lawyer must review it before you remove conditions. Key questions: Is the reserve fund adequately funded (look for a recent reserve fund study)? Are there any pending special assessments? What percentage of units are investor-owned vs owner-occupied (higher owner-occupancy = better maintained building)? Are pets, short-term rentals, or BBQs prohibited? Are there any ongoing lawsuits against the corporation?"], checklist: [] },
    { heading: "Which Is Right for You", paragraphs: ["Condos suit buyers who want urban locations, low exterior maintenance, and amenities — and can accept shared governance and restrictions. Freehold suits buyers who want control over their property, outdoor space, and no monthly fees — and can handle all maintenance themselves. For investors: check condo rules on rentals and short-term use before buying. For families: freehold's outdoor space often becomes important once children arrive."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Compare total monthly costs: mortgage + maintenance fees vs mortgage only", "Request and review status certificate (lawyer must review)", "Check reserve fund balance and recent study", "Check for any pending special assessments", "Review all condo rules and restrictions", "Confirm pet and rental policies", "Inspect parking and storage allocation", "Check owner-occupancy ratio", "Calculate realistic total cost of ownership for each option"] },
  ],
  "bidding-war-strategy": [
    { heading: "Set Your Ceiling Before You Bid", paragraphs: ["Decide your absolute maximum price before you walk into a competing offer situation — never in the heat of the moment. Calculate: what monthly payment does my max price create? Am I comfortable with that for 25 years? What do comparable recent solds support? If the bidding exceeds your ceiling, you must walk away. There will be another home. The buyers who regret bidding wars are always the ones who crossed their own line."], checklist: [] },
    { heading: "Escalation Clauses", paragraphs: ["An escalation clause says you will beat any competing bona fide offer by a set amount, up to a maximum. Example: 'I offer $760,000, or $5,000 above any competing offer, to a maximum of $795,000.' This keeps you competitive without bidding against yourself. Ask your agent whether the listing brokerage will accept escalation clauses — some refuse, requiring straight offers only."], checklist: [] },
    { heading: "What Sellers Want Besides Price", paragraphs: ["Closing date flexibility can win a deal even at a lower price. A larger deposit signals commitment and financial strength. Fewer conditions reduce the risk of the deal falling through. A well-structured $779,000 offer with confirmed financing can beat a $789,000 offer with uncertain approval. Find out from the listing agent what matters to the seller — sometimes it's timeline, sometimes it's certainty, rarely is it only price."], checklist: [] },
    { heading: "When to Walk Away", paragraphs: ["If bidding exceeds your ceiling, walk away without exception. If you're being pressured to remove your financing condition and you genuinely need it, walk away. In a balanced 2026 market, patience is a legitimate strategy. Overpaying by $50,000 in a bidding war means years of extra interest, reduced financial flexibility, and potential negative equity if values soften. The right home at the right price will come."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Set maximum price before viewing the home", "Confirm pre-approval is current", "Research recent sold prices for comparables", "Discuss escalation clause option with agent", "Prepare deposit funds in accessible account", "Find out seller's priorities from listing agent", "Confirm closing date flexibility", "Decide which conditions you will include or waive", "Know your walk-away number — and honour it"] },
  ],
  "home-inspection-guide": [
    { heading: "What a Home Inspector Examines", paragraphs: ["Roof: condition, estimated remaining life, visible defects. Foundation and structure: cracks, settling, evidence of water infiltration. Electrical: panel age and capacity, wiring type, grounding, GFCI protection. Plumbing: pipe material and condition, water heater age, water pressure. HVAC: furnace and AC age, condition, and efficiency. Insulation and ventilation: attic insulation depth and condition. Windows, doors, and exterior cladding. Note: inspectors do not open walls, move furniture, or test for radon — these require separate specialists."], checklist: [] },
    { heading: "How to Use the Inspection", paragraphs: ["Attend in person — this is non-negotiable. Walk through with the inspector, ask every question that occurs to you, and take your own notes and photos alongside theirs. Read the full report the same evening. Categorize findings: safety issues requiring immediate action, major defects costing $5,000+, and maintenance items that are normal for the home's age. Use major findings to renegotiate price, request repairs, or in serious cases, exercise your inspection condition to exit."], checklist: [] },
    { heading: "Red Flags That Change the Deal", paragraphs: ["Knob-and-tube or aluminum wiring: many insurers refuse coverage or charge significant premiums. Active water infiltration in the basement or foundation: expensive to properly remediate. Cracked or bowing foundation walls: structural repairs cost $10,000–$60,000+. Furnace or AC at end of life: $5,000–$15,000 to replace. Vermiculite insulation in the attic: may contain asbestos, requires professional testing and potential abatement ($5,000–$20,000). Polybutylene or Kitec plumbing: high failure risk, replacement $5,000–$15,000."], checklist: [] },
    { heading: "Waiving the Inspection — When and How", paragraphs: ["In competitive markets, some buyers waive inspection to win. This is a significant risk. Lower-risk alternatives: request the seller's pre-listing inspection report, hire your own inspector for a pre-offer inspection (before submitting), or use a short inspection condition window (24–48 hours). Never waive inspection on homes built before 1980, homes showing signs of deferred maintenance, or any home where the price makes an unexpected repair genuinely unaffordable."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Book licensed inspector before removing conditions", "Attend inspection in person", "Ask inspector to explain every finding", "Photograph all issues alongside inspector", "Categorize findings: safety / major / maintenance", "Decide if renegotiation is warranted", "Request seller disclosure on known defects", "Keep full report for future reference and insurance"] },
  ],
  "fhsa-guide": [
    { heading: "How the FHSA Works", paragraphs: ["Annual contribution limit: $8,000. Lifetime contribution limit: $40,000. Contributions are tax-deductible — reducing your taxable income in the year you contribute. Qualifying withdrawals for a first home purchase are completely tax-free with no repayment obligation. Unused annual contribution room carries forward, but only by one year at a time — meaning the maximum you can contribute in a single year is $16,000 (current year + one carry-forward). Available to Canadian residents aged 18–71 who have not owned a principal residence in the current year or the preceding 4 calendar years."], checklist: [] },
    { heading: "FHSA vs RRSP Home Buyers' Plan", paragraphs: ["RRSP HBP: withdraw up to $35,000 tax-free, but you must repay it to your RRSP over 15 years or the annual shortfall is added to your income. FHSA: no repayment required, ever. The FHSA is strictly superior dollar-for-dollar because of this. You can use both together: $40,000 FHSA withdrawal plus $35,000 RRSP HBP = $75,000 toward your down payment, with no repayment on the FHSA portion and a 15-year repayment on the RRSP portion."], checklist: [] },
    { heading: "When to Open Your FHSA", paragraphs: ["Open your FHSA as early as possible — even if you aren't planning to buy for 5+ years. The account must be open for at least one calendar year before you can make a qualifying tax-free withdrawal. Contribution room begins accumulating from the year you open the account, not from when you contribute. If you never buy a home, you can transfer the full balance to your RRSP or RRIF without affecting your RRSP contribution room — zero downside to opening it today."], checklist: [] },
    { heading: "What to Invest Inside Your FHSA", paragraphs: ["FHSAs hold the same investment options as RRSPs: GICs, ETFs, stocks, bonds, and mutual funds. Match your investment to your timeline. Buying in 1–2 years: use a high-interest savings account or GIC. Buying in 3–5 years: a conservative balanced ETF. Buying in 5+ years: consider a diversified equity ETF for growth potential. All major banks and discount brokerages (Questrade, Wealthsimple, TD, RBC, etc.) now offer FHSAs."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Confirm first-time buyer eligibility", "Open FHSA immediately (any amount)", "Set up $8,000 annual contribution", "Choose investment matching your timeline", "Track carry-forward contribution room", "Plan FHSA + RRSP HBP combination strategy", "Keep FHSA open minimum one calendar year before withdrawal", "Complete CRA Form RC725 for qualifying withdrawal", "Confirm withdrawal with your mortgage lender's process"] },
  ],
  "interest-rate-impact": [
    { heading: "The Direct Impact on Buying Power", paragraphs: ["At 4.5% on a 25-year amortization, a $4,000/month payment supports roughly $720,000 in mortgage. At 5.5%, the same payment supports about $650,000. At 6.5%, approximately $585,000. Each 1% rate increase reduces your buying power by around $70,000–$80,000 on a $4,000/month budget. When the Bank of Canada cuts rates, the reverse occurs — each 0.25% cut adds approximately $15,000–$20,000 in purchasing capacity for the same monthly payment."], checklist: [] },
    { heading: "Fixed vs Variable in 2026", paragraphs: ["Fixed rate: locked for your term (1–5 years typically). Guaranteed payments — you know exactly what you'll pay. Break penalties can be significant (Interest Rate Differential calculation). Variable rate: moves with the Bank of Canada prime rate. Historically costs less over a full amortization period but with uncertain monthly payments. In a rate-falling environment (as in late 2024–2025), variable rate holders have benefited significantly. Discuss your risk tolerance with your broker honestly."], checklist: [] },
    { heading: "The Stress Test and Rate Changes", paragraphs: ["The federal stress test requires you to qualify at the higher of your offered rate plus 2%, or 5.25%. When offered rates were 5.5%, buyers had to qualify at 7.5% — dramatically reducing purchase price eligibility. As rates fall below 3.25%, the 5.25% floor becomes the binding constraint. Understanding where rates are relative to this floor affects how much the stress test is currently restricting buying power for your situation."], checklist: [] },
    { heading: "Practical Rate Strategy", paragraphs: ["Lock a pre-approval rate for 90–120 days and watch for rate drops before closing — most lenders will give you the lower rate if it drops. Get quotes from at least 3 lenders; the posted rate is never the best rate. Mortgage brokers typically access wholesale rates from 30+ lenders simultaneously — their service is usually free (paid by the lender). Even 0.15% difference on a $700,000 mortgage saves over $1,000 per year."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate buying power at current rates", "Model a 1% rate increase to test your buffer", "Discuss fixed vs variable with mortgage broker", "Lock rate hold for 90–120 days", "Compare minimum 3 lenders", "Ask each lender about rate drop protection policy", "Factor stress test into maximum purchase price", "Monitor Bank of Canada announcement dates"] },
  ],
  "property-tax-guide": [
    { heading: "How Property Tax Is Calculated", paragraphs: ["Property tax = assessed value × mill rate. Your municipality assesses your property's value (annually in some provinces, on a cycle in others). The mill rate is set by the municipality and often includes a provincial education component. On a home assessed at $700,000 in Toronto with a combined rate of approximately 0.66%, annual property tax is about $4,620 — or $385/month. Rates vary dramatically by municipality: Hamilton's rate is higher than Toronto's; suburban areas differ from urban cores. Always ask the selling agent for the current property tax amount before making an offer."], checklist: [] },
    { heading: "Assessed Value vs Market Value", paragraphs: ["Assessed value is determined by MPAC in Ontario (or equivalent provincial bodies elsewhere) and often lags market value by 1–3 years in rising markets. New homes are frequently reassessed the year after purchase, which can trigger a significant increase in property tax that you were not warned about. You can appeal your assessment if you believe it overstates the value — the process is free and worth doing if your assessment seems high relative to what comparable homes sold for around your assessment date."], checklist: [] },
    { heading: "How You Pay Property Tax", paragraphs: ["If you have a mortgage, many lenders collect property tax monthly as part of your blended payment and remit it to the municipality on your behalf. Confirm this arrangement with your lender — it affects your monthly payment calculation. If you pay directly, most municipalities offer monthly, quarterly, or annual schedules. Pre-authorized payment plans help with budgeting and sometimes earn small discounts."], checklist: [] },
    { heading: "Closing Day Property Tax Adjustment", paragraphs: ["On closing day, your lawyer calculates a property tax adjustment. If the seller has prepaid property tax covering months after your closing date, you reimburse them for their prepayment on a per-diem basis. Conversely, if taxes are in arrears at closing, the seller pays you. This adjustment appears on your statement of adjustments — ask your lawyer to explain it before you sign."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Ask agent for current annual property tax on target homes", "Research MPAC assessment vs purchase price", "Confirm property tax payment method with lender", "Check if taxes are current with no arrears", "Ask lawyer about closing day property tax adjustment", "Budget for post-purchase reassessment", "Check for senior or disability tax rebates if eligible", "Note your appeal deadline after receiving assessment notice"] },
  ],
  "new-build-vs-resale": [
    { heading: "New Build Advantages", paragraphs: ["Tarion warranty (Ontario): 1 year for defects and workmanship, 2 years for electrical/plumbing/heating systems, 7 years for structural defects. Modern construction: better energy efficiency, insulation standards, and building codes. Customization of finishes during construction. 30-year insured amortization now available for first-time buyers of new builds. GST/HST New Housing Rebate may partially offset tax on homes under $450,000."], checklist: [] },
    { heading: "New Build Risks", paragraphs: ["Builder pricing: the advertised price is a base — every upgrade adds cost, and 'standard finishes' are often outdated deliberately to drive upgrade revenue. Construction delays are routine; budget for carrying costs if your rate hold expires. Development charges can be passed to the buyer at closing — check your Agreement of Purchase and Sale carefully. Phantom closings on assignment sales carry complex tax implications since 2022 HST rule changes. Assignment sales now attract HST on the profit."], checklist: [] },
    { heading: "Resale Advantages", paragraphs: ["What you see is what you get — inspect it before you buy and know exactly what you're getting. Move in on a fixed, reliable closing date. Established neighbourhood with mature trees, confirmed transit, and known schools. Negotiation on price, conditions, and inclusions is possible. No HST on most resale homes — only land transfer tax and legal fees. Resale condos and houses have a rental history and maintenance record you can request."], checklist: [] },
    { heading: "Resale Risks and Costs", paragraphs: ["Older building systems (roof, furnace, electrical panel, plumbing) may be near end of useful life — budget for replacement. Older homes may have legacy issues: knob-and-tube wiring, Kitec or polybutylene plumbing, asbestos insulation or pipe wrap. Less energy efficient than new builds, meaning higher utility costs. No structural warranty — the inspection is your only protection; never skip it on a resale."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Compare total cost: new build base + upgrades + delays vs resale + inspection repairs", "Check Tarion warranty details for specific builder", "Confirm new build closing timeline and current rate hold", "Review builder's Agreement of Purchase and Sale with a lawyer", "Check HST new housing rebate eligibility", "Inspect resale thoroughly with licensed inspector", "Research builder reputation and past project reviews", "Compare neighbourhood maturity and transit for both options"] },
  ],
  "bidding-offer-strategy": [
    { heading: "Components of an Offer", paragraphs: ["Purchase price: your offer amount. Deposit: funds paid into trust within 24 hours of acceptance — typically 5% of purchase price. Closing date: when ownership transfers. Conditions: clauses that must be satisfied for the deal to proceed. Inclusions and exclusions: appliances, fixtures, window coverings — specify everything. Irrevocable period: how long the offer is open for acceptance before it expires — typically 24–48 hours in standard markets."], checklist: [] },
    { heading: "Conditions Explained", paragraphs: ["Financing condition: gives you a specified number of days (typically 5) to confirm mortgage approval. Protects you if the lender won't approve the specific property. Inspection condition: gives you a specified number of days to complete a home inspection and review the results. You can waive the condition if satisfied, negotiate repairs/price, or exit if the results are unacceptable. Status certificate condition: for condos — gives your lawyer time to review the condo corporation's financial and legal status."], checklist: [] },
    { heading: "Schedule A: Your Protection Clauses", paragraphs: ["Schedule A is where your agent adds protective clauses to the standard form. Common additions: seller warrants no work orders or outstanding permits, WETT certificate for wood-burning fireplace, specific items confirmed included (fridge, stove, washer/dryer, EV charger), and confirmation of vacant possession on closing. Review Schedule A carefully — these clauses are negotiated, not standard."], checklist: [] },
    { heading: "Counter-Offers and Negotiation", paragraphs: ["A counter-offer creates a new irrevocable period and voids the original offer. You can counter on price, conditions, closing date, inclusions, or any combination. In a balanced market, 2–3 rounds of negotiation is common on standard sales. Keep emotion out of the negotiation — every decision should be based on comparable solds, your budget, and the property's condition. Your agent is your negotiator; trust their read of the situation."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Review standard APS form with your agent before offer night", "Confirm deposit funds are accessible within 24 hours", "Discuss which conditions to include", "Review Schedule A protective clauses", "Set irrevocable period appropriately for market conditions", "Confirm all inclusions and exclusions in writing", "Review counter-offer implications with agent", "Keep copies of every signed version of the offer", "Confirm firm deal in writing when conditions waived"] },
  ],
  "land-transfer-tax": [
    { heading: "Ontario Land Transfer Tax", paragraphs: ["On the first $55,000: 0.5%. $55,001–$250,000: 1.0%. $250,001–$400,000: 1.5%. $400,001–$2,000,000: 2.0%. Above $2,000,000: 2.5% on non-residential. Example: $800,000 home in Ontario = $12,475. Toronto buyers pay a second identical municipal LTT, making total LTT on an $800,000 Toronto home approximately $24,950. First-time buyer provincial rebate: up to $4,000. Toronto first-time buyer rebate: up to $4,475. Combined rebates can reduce Toronto LTT by approximately $8,475 for eligible first-time buyers."], checklist: [] },
    { heading: "British Columbia Property Transfer Tax", paragraphs: ["First $200,000: 1%. $200,001–$2,000,000: 2%. Above $2,000,000: 3%. Additional 2% on the residential portion above $3,000,000. First-time buyer exemption: full PTT exemption on homes purchased for $500,000 or less; partial exemption on homes $500,001–$525,000. New housing exemption available for qualifying new builds. Foreign buyer additional property transfer tax: 20% in Metro Vancouver and other specified areas."], checklist: [] },
    { heading: "Alberta and Saskatchewan: No LTT", paragraphs: ["Alberta has no provincial land transfer tax — one of the most significant cost advantages for buyers relocating from Ontario or BC. Instead, Alberta charges a land title transfer fee based on property value, typically $500–$1,500 — a fraction of LTT in other provinces. Saskatchewan similarly has no LTT, only land title registration fees. This is a material financial advantage that partially explains why these provinces attract interprovincial migration."], checklist: [] },
    { heading: "Other Provinces", paragraphs: ["Quebec (Bienvenue Tax): 0.5% on first $58,900; 1.0% on $58,901–$294,600; 1.5% above. Montreal properties may add a supplemental municipal tax. Manitoba: tiered from 0%–2% based on price. New Brunswick, Nova Scotia, PEI, and Newfoundland: each has its own deed transfer tax ranging from 0.5%–1.5%. Calculate your province's exact LTT before making an offer — it affects your total budget significantly."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Calculate LTT for your specific province and municipality", "Check first-time buyer rebate eligibility in your province", "Confirm Toronto municipal LTT if buying within Toronto", "Factor LTT into total closing cost budget", "Ask lawyer to confirm LTT calculation before closing", "Check PTT new build exemption eligibility (BC)", "Research Alberta/Saskatchewan advantages if relocating", "Request LTT rebate application process from your lawyer"] },
  ],
  "home-staging-budget": [
    { heading: "The Psychology of Staging", paragraphs: ["Buyers make an emotional purchase decision within seconds of entering a home. They are buying a lifestyle, not square footage. Your job as a seller is to remove your personality from the space and replace it with neutral, aspirational calm — not sterile and empty, but clean and uncluttered enough that buyers can project their own lives into it. Staging is not about hiding the home's features; it's about letting them breathe."], checklist: [] },
    { heading: "Free and Low-Cost High-Impact Changes", paragraphs: ["Declutter ruthlessly — remove 30–40% of furniture and all personal photos and memorabilia. Deep clean including baseboards, light fixtures, tops of cabinets, and inside appliances. Clear every kitchen counter completely. Fresh neutral paint (white, soft grey, or warm greige) is the single highest-ROI update in real estate — one coat transforms a dated room. Clean all windows inside and out — natural light sells. Replace dated light fixtures: $30–$80 each at IKEA or Home Depot makes a visible difference."], checklist: [] },
    { heading: "Curb Appeal — First Impressions Are Non-Negotiable", paragraphs: ["Buyers form their impression before they open the front door. Power wash the driveway and front walkway. Repaint the front door a strong, welcoming colour — black, navy, or deep red all perform well. New house numbers and a mailbox cost $20–$60 and look fresh. Fresh mulch in garden beds and two potted plants flanking the entry take a Saturday morning and cost under $200. Photography of the exterior happens on listing day — these improvements need to be done first."], checklist: [] },
    { heading: "When Professional Staging Is Worth It", paragraphs: ["Hire a professional stager for: vacant homes (empty rooms photograph terribly and make spaces feel smaller), luxury properties where the staging investment is proportionally small, and homes where your existing furniture is very personal, very dated, or very large for the space. Professional stagers bring rental furniture and accessories and — most importantly — they see your home the way a buyer does. Their fee is typically recovered in the final sale price."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Declutter 30–40% of every room", "Remove all personal photos and memorabilia", "Deep clean including baseboards and inside appliances", "Refresh paint in main living areas", "Clean all windows inside and out", "Replace any visibly dated light fixtures", "Clear kitchen and bathroom counters completely", "Power wash driveway and front walkway", "Repaint front door", "Add two potted plants at entry", "Book professional photography only after staging is complete"] },
  ],
  "when-to-list": [
    { heading: "Spring: The Traditional Peak", paragraphs: ["March through May is historically the strongest selling season in Canadian real estate. Buyers who delayed over winter return to the market. Families want to close in time for the September school year. Good weather makes homes show better and photograph more attractively. More active buyers mean more competition among purchasers — days on market are typically shortest in April and May in most markets."], checklist: [] },
    { heading: "Fall: The Second Window", paragraphs: ["September through October is the second-strongest window. Summer vacation buyers return with renewed urgency. Inventory drops in November as sellers wait for spring, which can favour October listers. In 2026, fall is expected to be particularly active in Ontario and BC as Bank of Canada rate cuts bring buyers back who had been sidelined."], checklist: [] },
    { heading: "Winter: The Contrarian Advantage", paragraphs: ["December through February has fewer listings — which means less competition. Buyers active in winter are serious; casual browsers stay home. Homes often photograph beautifully with exterior lighting and cozy interior staging. The strategic window: list in late January when buyer demand picks up but spring inventory has not yet arrived. Less competition with motivated buyers is often better than peak season with 40 competing listings."], checklist: [] },
    { heading: "When Timing Doesn't Matter", paragraphs: ["A well-priced, well-presented home in any market condition will sell. Your personal circumstances — job relocation, estate, life change, financial need — matter more than the calendar. A skilled agent can compensate for timing through pricing strategy, marketing, and preparation. If you're ready to sell, the best time is when your home is prepared and priced correctly — not an arbitrary calendar date."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Identify your target listing window 8–12 weeks ahead", "Discuss seasonal timing strategy with your agent", "Review current inventory levels in your specific area", "Check average days on market for comparables", "Start staging and repair prep 4–6 weeks before list date", "Book photographer and stager well in advance", "Set price strategy appropriate for your chosen season", "Plan for school-year closing if targeting families"] },
  ],
  "commission-negotiation": [
    { heading: "How Commission Works Today", paragraphs: ["Total commission has traditionally been 3.5%–5% of the sale price, split between the listing brokerage and the buyer's brokerage, with the seller paying both. On an $850,000 home at 4%, that's $34,000 — typically the largest line item after the mortgage payout. Following Canadian real estate industry changes in late 2024, buyer agent compensation structures are now disclosed differently in some markets — ask your listing agent to explain the current structure in your area."], checklist: [] },
    { heading: "What Full Commission Pays For", paragraphs: ["A full-service listing agent provides: a comparative market analysis and pricing strategy, professional photography and virtual tour, MLS listing and digital marketing, open houses and private showings, offer review and negotiation expertise, and coordination with your lawyer through closing. In a competitive market with a motivated seller, a skilled agent can net you significantly more than their commission costs — the question is always total net proceeds, not commission percentage."], checklist: [] },
    { heading: "How to Negotiate Effectively", paragraphs: ["Interview three agents before signing anything. Ask each one: what is your total commission, what does it include, how much goes to the buyer's agent, and what specifically will you do differently to market my home? Some agents reduce their side for repeat clients, luxury properties (where percentage translates to large dollar amounts), or if you're also buying with them. Discount brokerages offer 1%–1.5% for listing only — appropriate for sellers who are experienced and need less support."], checklist: [] },
    { heading: "What Not to Do", paragraphs: ["Don't offer a below-market buyer's agent commission — it reduces motivation for buyer agents to show your property, which reduces buyer traffic. Don't choose an agent on the lowest commission alone — a better agent who prices and markets correctly typically nets more money even at a higher commission rate. Always get the full commission structure in writing in the listing agreement before signing."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Interview minimum three agents before signing", "Ask each agent to detail their total commission structure", "Confirm buyer agent compensation being offered", "Compare marketing plans and track records, not just rates", "Get full commission terms in writing in listing agreement", "Calculate net proceeds at different commission scenarios", "Ask for references from recent sellers", "Negotiate from knowledge, not pressure"] },
  ],
  "capital-gains-guide": [
    { heading: "The Principal Residence Exemption", paragraphs: ["If a property was your principal residence for every year you owned it, the entire capital gain is tax-exempt. You may only designate one property per family unit as a principal residence per year. The exemption does not apply automatically — you must file Schedule 3 and Form T2091 with your tax return in the year of sale. The exemption generally still applies even if you rented out a portion of the home (a basement suite), provided your primary purpose was personal use and you did not make a structural change to create a separate unit."], checklist: [] },
    { heading: "When Capital Gains Tax Applies", paragraphs: ["You rented the entire property for a period during ownership. You purchased with the primary intent to resell (flipping). You own multiple properties and cannot designate this one for the full period. You are a non-resident of Canada. British Columbia introduced a Home Flipping Tax in January 2025 for BC residential properties held less than 730 days — this is separate from and in addition to the federal capital gains rules. Check both rules if selling a BC property held short-term."], checklist: [] },
    { heading: "How Capital Gains Are Taxed", paragraphs: ["Your capital gain = sale price minus adjusted cost base (ACB) minus selling costs. ACB = original purchase price plus eligible capital improvements (new roof, addition, kitchen renovation — documented with receipts). 50% of capital gains are included in taxable income for individuals (the inclusion rate). For gains over $250,000, the 2024 federal Budget proposed increasing the inclusion rate to 2/3 — consult an accountant as this was still evolving legislatively. Your effective tax on the gain depends on your marginal tax bracket."], checklist: [] },
    { heading: "Tax Planning Before You Sell", paragraphs: ["Keep every receipt for capital improvements — they increase your ACB and reduce taxable gain. Renovations that qualify: new kitchen, bathroom addition, deck, landscaping, new roof, added floor. Repairs do not qualify — only capital improvements. Consult a tax accountant before selling any property that was ever rented or used for income purposes. Non-residents selling Canadian property must obtain a Section 116 clearance certificate and withhold 25% of gross proceeds — failure results in the buyer becoming liable."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Confirm your principal residence designation years", "Gather all capital improvement receipts for ACB calculation", "Consult accountant if property was ever rented", "File T2091 and Schedule 3 in year of sale", "Check BC flipping tax if applicable", "Check non-resident rules if applicable", "Calculate estimated capital gain before accepting offer", "Plan for tax payment — due April 30 following year of sale"] },
  ],
  "selling-in-winter": [
    { heading: "Why Winter Can Be Your Advantage", paragraphs: ["The competitive reality of spring listing is that your home launches alongside dozens of similar properties — buyers have options and negotiate harder. In winter, inventory is thin. Buyers actively searching in January and February are serious purchasers, often with specific timelines (job relocation, lease ending, life change). Your well-presented home faces less competition for each motivated buyer. January listings that are priced right frequently sell in the first two weeks."], checklist: [] },
    { heading: "Preparing Your Home for Winter Showings", paragraphs: ["Exterior: keep driveways and walkways clear of snow and ice — this is essential and must be done before every showing. Use exterior lighting on timers to compensate for early darkness (listings go live before dark at 4pm). Take summer photos of landscaping and garden before the snow falls — save them for the MLS listing to show seasonal potential. Interior: ensure the home is warm but not hot (buyers keep coats on at showings). Create a genuinely cozy atmosphere: fireplace on, warm lighting, subtle neutral scent."], checklist: [] },
    { heading: "Pricing in a Winter Market", paragraphs: ["Do not underprice your home simply because it's winter. A correct price in thin inventory often generates as much interest as spring — sometimes more per listing. Use comparable sold prices from the past 90–120 days to set the price. If the most recent comparables are from spring, your agent should adjust for seasonal factors. Winter listings that are priced correctly typically receive offers within two to three weeks; those priced high sit through winter and into spring, losing momentum."], checklist: [] },
    { heading: "Timing Within the Winter Season", paragraphs: ["Avoid listing between December 20 and January 2 — most buyers, agents, and lawyers are on holiday. Late January through February is the strongest winter window: holiday buyers have returned, new-year motivation is high, and spring inventory hasn't arrived yet. By early March, spring listings begin appearing — if you list in late February, you're often ahead of the main inventory wave rather than competing with it."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Save summer exterior and garden photos before snow", "Set exterior lighting on timers before listing", "Maintain clear driveway and walkways for every showing", "Ensure furnace is serviced and working reliably", "Stage for warmth and coziness", "Price at market value — no winter discount required", "List late January to February for best winter timing", "Avoid holiday dead period (December 20 – January 2)", "Brief your agent on showings communication expectations"] },
  ],
  "upgrading-vs-downsizing": [
    { heading: "Upsizing: Managing the Timing Gap", paragraphs: ["Most upsizers want to sell their current home before committing to a new purchase — but sellers of the new property want certainty. Solutions: bridge financing (a short-term loan from your current lender to cover the gap between your sale closing and purchase closing — ask about eligibility and rate). A condition of sale on your purchase is acceptable in slower markets but rarely tolerated in competitive ones. Flexible closing dates of 60–90 days after your own sale give you time to find the next property without pressure."], checklist: [] },
    { heading: "Downsizing: The Math and the Surplus", paragraphs: ["Calculate your net proceeds: sale price minus mortgage payout, commission, legal fees, and closing costs. Calculate your new purchase cost: purchase price plus LTT, legal fees, and moving. The difference is your freed equity — for most long-time homeowners, this can be substantial. Invest surplus wisely and tax-efficiently: RRSP top-up, TFSA, GICs — consult a financial advisor before deploying large sums. Freed equity invested correctly can generate meaningful retirement income."], checklist: [] },
    { heading: "Tax and Government Benefit Implications", paragraphs: ["If both properties qualify as principal residences, the PRE fully applies to both capital gains — no tax. If either property was ever rented, capital gains apply to the rental period. Downsizers in retirement: freed equity invested and generating income may affect OAS and GIS clawback thresholds. Plan the transition with a financial advisor and accountant before you sell, not after — some decisions (like RRSP vs TFSA allocation) need to be made in advance."], checklist: [] },
    { heading: "Bridge Financing Details", paragraphs: ["Bridge financing is available from most major banks and credit unions for terms of 90–180 days. The rate is typically prime plus 2%–3% — higher than your mortgage rate. Eligibility requires a firm sale on your existing property (conditions must be waived) and an accepted purchase on the new one. The bank bridges the equity gap. Minimize the bridge period to reduce the cost — aim for same-day or same-week closings if your agent can coordinate it."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Get home valuation to estimate net proceeds", "Calculate target purchase price based on projected proceeds", "Ask lender about bridge financing eligibility and cost", "Work with agent to align closing dates", "Confirm principal residence years for tax purposes", "Consult accountant if either property was ever rented", "Meet with financial advisor before deploying freed equity", "Consider OAS/GIS implications if in retirement", "Plan storage if significant downsizing of belongings"] },
  ],
  "prelisting-inspection": [
    { heading: "What a Pre-Listing Inspection Is", paragraphs: ["You hire a licensed home inspector — the same type of inspector a buyer would hire — to inspect your property before it goes on MLS. You receive the full report. You then decide what to repair, what to disclose, and how to price the known condition of the home. Cost is identical to a buyer's inspection: $400–$600. The investment typically pays back many times over in avoided post-offer renegotiations."], checklist: [] },
    { heading: "The Strategic Advantages", paragraphs: ["Eliminates surprise renegotiations: when a buyer's inspector discovers a significant defect after offer acceptance, buyers routinely ask for $10,000–$30,000 in price reductions. A pre-listing inspection lets you address these on your own terms — fix them, price them in, or disclose them transparently. In competitive markets, you can share the pre-inspection report with buyers, encouraging them to submit firm offers without conditions — extremely attractive in multiple offer situations. Transparency about your home's condition builds trust and signals confidence."], checklist: [] },
    { heading: "What to Do With the Report", paragraphs: ["Fix high-priority safety items before listing — buyers and their agents notice flagged safety issues immediately. For major items you choose not to repair (aging furnace, roof near end of life), price them into your asking price and disclose them proactively rather than waiting for the buyer to discover them. Undisclosed known defects are grounds for legal action post-closing — disclosure protects you legally. Keep documentation of all repairs made following the inspection."], checklist: [] },
    { heading: "When a Pre-Listing Inspection May Not Be Needed", paragraphs: ["Very new homes (under 5 years old) where systems are under warranty. Selling as-is for estate purposes or land value. Homes you are certain are in excellent condition throughout. For any home built before 1980, any home with past water infiltration history, or any property where you have deferred maintenance over multiple years, a pre-listing inspection is nearly always worth the cost relative to the avoided renegotiation losses."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Decide if pre-listing inspection makes sense for your property", "Book licensed, certified home inspector", "Attend inspection in person — bring a notepad", "Review full report with your agent", "Prioritize: which items to fix before listing", "Get quotes for major repairs before deciding", "Develop disclosure strategy with agent", "Update listing price to reflect home's documented condition", "Keep all repair invoices for the disclosure package", "Consider sharing report with buyers to encourage firm offers"] },
  ],
  "moving-timeline": [
    { heading: "10–12 Weeks Before Closing", paragraphs: ["Hire your listing agent. Discuss pre-listing inspection. Begin decluttering aggressively — start rooms you use least. Research your next destination: if buying, get pre-approved. If renting, begin searching. Notify your mortgage lender that a sale may be coming — get a payout statement to understand any penalty."], checklist: [] },
    { heading: "6–8 Weeks Before Closing", paragraphs: ["Complete all repairs and touch-ups identified in pre-listing inspection. Paint, clean, and stage your home. Book professional photographer for 1–2 weeks before list date. Agent prepares MLS listing, floor plans, and marketing materials. Confirm your next housing plan and timeline."], checklist: [] },
    { heading: "Listing Through Firm Deal", paragraphs: ["Home goes live on MLS. Showings begin immediately — keep home show-ready at all times. Review offers with agent as they come. Negotiate, accept, and begin conditions period (typically 5–10 business days). Conditions waived: deal is firm. Book your moving company the same day the deal firms — good movers book up weeks in advance."], checklist: [] },
    { heading: "Firm Deal to Closing", paragraphs: ["Begin packing non-essential items. Notify utilities of your closing date. Give required notice to your condo building if applicable. Hire real estate lawyer if not already retained. Update your address with Canada Post, CRA, bank, employer, subscriptions. Complete final clean and touch-ups. Vacate the property by the agreed time on closing day — typically by 6pm. Your lawyer receives funds from the buyer's lawyer and releases keys after confirming receipt."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Hire agent 10–12 weeks before target listing", "Complete pre-listing inspection", "Finish all repairs and staging", "Book photographer", "Accept and firm up offer", "Book moving company immediately after firm deal", "Notify utilities of closing date", "Update Canada Post address", "Hire real estate lawyer", "Pack all non-essentials during conditions period", "Final clean and walkthrough", "Vacate by agreed time on closing day", "Confirm receipt of net proceeds from lawyer"] },
  ],
  "market-outlook-2026": [
    { heading: "Where the Market Stands in 2026", paragraphs: ["After the Bank of Canada reduced rates to a multi-year low in late 2024–2025, buyer activity has returned to most major markets. Ontario, Quebec, and BC are in balanced-to-buyer territory with 4–6 months of available inventory. Alberta and parts of Atlantic Canada remain more supply-constrained and seller-friendly. The bidding-war frenzy of 2021 has been replaced by a more selective market where buyers distinguish carefully between well-presented homes and overpriced listings."], checklist: [] },
    { heading: "What This Means for Pricing Strategy", paragraphs: ["Pricing correctly from day one matters more than ever in a balanced market. Overpriced homes accumulate days on market, attract low-ball offers, and stigmatize — buyers assume something is wrong. A well-priced home in good condition still attracts competitive interest, sometimes multiple offers. The market has shifted from 'any home sells' to 'the right home at the right price sells' — the difference is presentation and pricing discipline."], checklist: [] },
    { heading: "Segment-Specific Conditions", paragraphs: ["Toronto and Vancouver condo markets remain softer than freehold due to elevated investor-owned inventory and assignment sales pressure. Ground-level freehold in suburban and commuter markets is firming as buyers prioritize space. New construction is competitive due to 30-year amortization availability for first-time buyers. Investors selling rental condos are adding inventory in major cities — if you own a rental condo, price for this competitive environment."], checklist: [] },
    { heading: "Interest Rate Trajectory and Its Effect on Sellers", paragraphs: ["Falling rates increase buyer qualification and return sidelined buyers to the market — this is positive for sellers. Fixed-rate mortgage holders from 2022–2023 face renewal pressure in 2025–2027; some will sell to right-size payments, adding inventory in specific price ranges. Watch renewal volumes in your market segment — this affects your competition. Each Bank of Canada cut adds approximately 2–3% to buyer purchasing power, which gradually firms prices as demand increases."], checklist: [] },
    { heading: "Checklist", paragraphs: [], checklist: ["Get current CMA based on last 90 days of sales", "Check months of inventory in your specific price range", "Review days on market for comparable homes", "Understand condo vs freehold dynamics in your area", "Price at market from day one", "Plan for 30–60 day market time in balanced conditions", "Monitor Bank of Canada rate decisions", "Discuss renewal volume impact with your agent", "Review your mortgage payout statement early"] },
  ],
};
